const XLSX = require\('xlsx'\);
const fs = require\('fs'\);
const path = 'C:/Apextime.cloud/apextime.cloud/compoff.xlsx';
const wb = XLSX.readFile\(path, { cellFormula: true, cellHTML: false, cellText: true, sheetStubs: true }\);

let output = '';
output += '=== SHEETS ===\\n';
output += JSON.stringify\(wb.SheetNames\) + '\\n';

wb.SheetNames.forEach\(name => {
  const ws = wb.Sheets[name];
  output += '\\n\\n====== SHEET: ' + name + ' ======\\n';
  if \(ws['!merges']\) {
    output += 'MERGED CELLS: ' + JSON.stringify\(ws['!merges']\) + '\\n';
  }
  const range = XLSX.utils.decode_range\(ws['!ref'] || 'A1:A1'\);
  output += 'RANGE: ' + ws['!ref'] + '\\n';
  for \(let R = range.s.r; R <= range.e.r; R++\) {
    let row = [];
    for \(let C = range.s.c; C <= range.e.c; C++\) {
      const addr = XLSX.utils.encode_cell\({r: R, c: C}\);
      const cell = ws[addr];
      if \(cell\) {
        const val = cell.f ? \('FORMULA: ' + cell.f\) : \(cell.v !== undefined ? cell.v : ''\);
        row.push\(addr + '=' + JSON.stringify\(val\)\);
      }
    }
    if \(row.length\) output += 'Row ' + \(R+1\) + ': ' + row.join\(' | '\) + '\\n';
  }
}\);

fs.writeFileSync\('C:/Apextime.cloud/apextime.cloud/compoff_extracted.txt', output\);
console.log\('Written to compoff_extracted.txt, size:', output.length, 'chars'\);
" 2>&1)

